'use client';

/*
 * Consent banner, "pelure" style — generated by `zeste add --style pelure`, yours to edit.
 * Colors: ./theme.css. "Deny all" and "Accept all" deliberately have
 * exactly the same style (EU consent rules: equal prominence).
 */
import { ConsentBanner, useZeste } from '@zeste/react';
import type { Messages } from '@zeste/services/i18n/types';
import './theme.css';

const focus = 'focus-visible:outline-[3px] focus-visible:outline-offset-[3px] focus-visible:outline-(--zeste-ink)';
const button = `inline-flex items-center justify-center rounded-[10px] border-[2.5px] border-(--zeste-ink) bg-(--zeste-card) px-[18px] py-2.5 text-sm font-bold text-(--zeste-ink) shadow-[4px_4px_0_var(--zeste-ink)] transition-transform active:translate-x-[2px] active:translate-y-[2px] active:shadow-[2px_2px_0_var(--zeste-ink)] ${focus}`;
const link = `rounded-sm px-2 py-2.5 text-sm font-bold text-(--zeste-ink) underline underline-offset-[3px] ${focus}`;

export function CookieBanner() {
  const zeste = useZeste<Messages>();
  const t = zeste.messages;

  return (
    <>
      {zeste.needsReload && (
        // An already-loaded script was refused: it only really stops on reload.
        <div
          role="status"
          data-zeste-skin="pelure"
          className="fixed top-4 right-4 z-50 rounded-[14px] border-[3px] border-(--zeste-ink) bg-(--zeste-paper) p-3 shadow-[6px_6px_0_var(--zeste-ink)]"
        >
          <button type="button" className={button} onClick={() => location.reload()}>
            {t.reload}
          </button>
        </div>
      )}

      <ConsentBanner
        data-zeste-skin="pelure"
        aria-label={t.icon}
        className="fixed inset-x-0 bottom-0 z-50 flex flex-wrap items-center gap-x-6 gap-y-3.5 border-t-[3px] border-(--zeste-ink) bg-(--zeste-paper) px-6 py-5 text-(--zeste-ink)"
      >
        <div className="grid min-w-0 flex-[1_1_20rem] gap-1">
          <span className="text-2xl leading-none font-extrabold tracking-tight">{t.icon}</span>
          <p className="text-[15px] font-medium">{t.alertBigPrivacy}</p>
        </div>
        <div className="flex flex-wrap items-center gap-2.5">
          <button type="button" className={button} {...zeste.actions.denyAll}>
            {t.denyAll}
          </button>
          <button type="button" className={button} {...zeste.actions.acceptAll}>
            {t.acceptAll}
          </button>
          <button type="button" className={link} {...zeste.actions.openPreferences}>
            {t.personalize}
          </button>
        </div>
      </ConsentBanner>
    </>
  );
}
